def qualifying_geometry(current,previous,atr,prior_high):
    _,opening,high,low,close = current
    _,previous_open,previous_high,previous_low,previous_close = previous
    engulf = previous_close>previous_open and close<opening and opening>=previous_close and close<=previous_open
    if not engulf or atr is None or atr<=0 or high<=low or previous_high<=previous_low:
        return False,None
    details = dict(atr14=atr,prior60_high=prior_high,body_atr=abs(opening-close)/atr,
                   range_atr=(high-low)/atr,abs_high_distance_atr=abs(high-prior_high)/atr,
                   signal_close_location=(close-low)/(high-low),
                   previous_close_location=(previous_close-previous_low)/(previous_high-previous_low))
    r = SHORT_RULE
    good = (details['body_atr']>=r['body_min_atr'] and details['range_atr']>=r['range_min_atr']
            and details['abs_high_distance_atr']<=r['distance_atr']
            and details['signal_close_location']<=r['signal_close_max']
            and details['previous_close_location']>=r['previous_close_min'])
    return good,details

def identify_original(hourly):
    atr = wilder_series(hourly)
    indices,features = [],[]
    patterns = 0
    for index in range(200,len(hourly)):
        bar,previous = hourly[index],hourly[index-1]
        if not (previous[4]>previous[1] and bar[4]<bar[1] and bar[1]>=previous[4] and bar[4]<=previous[1]):
            continue
        patterns += 1
        prior = max(b[2] for b in hourly[index-60:index])
        good,detail = qualifying_geometry(bar,previous,atr[index],prior)
        if detail is not None:
            features.append(dict(signal_index=index,signal=stamp(bar[0]),qualifies_original=int(good),**detail))
        if good:
            indices.append(index)
    return indices,features,patterns,atr

def isolated_path(hourly,index,model):
    if model not in MODELS:
        raise ValueError('Unknown execution model')
    signal = hourly[index]
    time,_,high,_,reference = signal
    stop = high+10*TICK
    target = reference-3.5*(stop-reference)
    out = dict(signal_index=index,signal=stamp(time),entry=stamp(time+HOUR),reference_entry=reference,
               stop=stop,target=target,next_open=None,next_candle_delay_hours=None,exit_index=None,exit=None,
               exit_price=None,reason='OPEN_AT_DATA_END',dual_touch=0,gap_stop=0,gap_target=0)
    if index+1<len(hourly):
        out['next_open'] = hourly[index+1][1]
        out['next_candle_delay_hours'] = (hourly[index+1][0]-time-HOUR).total_seconds()/3600
    for cursor in range(index+1,len(hourly)):
        time,opening,hi,lo,_ = hourly[cursor]
        hit_stop,hit_target = hi>=stop,lo<=target
        if not hit_stop and not hit_target:
            continue
        exit_time = time+HOUR
        stop_gap = target_gap = False
        if model=='STOP_FIRST_GAP_STRESS' and opening>=stop:
            price = max(opening,stop)
            stop_gap = opening>stop
            reason = 'STOP_GAP' if stop_gap else 'STOP'
            exit_time = time
        elif model=='STOP_FIRST_GAP_STRESS' and opening<=target:
            price,reason,target_gap,exit_time = target,'TARGET_GAP_CAPPED',True,time
        else:
            choose_stop = hit_stop
            if model=='SCREEN_PARITY' and hit_stop and hit_target:
                choose_stop = abs(hi-opening)<=abs(opening-lo)
            price,reason = (stop,'STOP') if choose_stop else (target,'TARGET')
        out.update(exit_index=cursor,exit=stamp(exit_time),exit_price=price,reason=reason,
                   dual_touch=int(hit_stop and hit_target),gap_stop=int(stop_gap),gap_target=int(target_gap))
        return out
    return out

def price_entry(path,cost):
    fill = path['reference_entry']-cost*TICK
    if date(path['entry'])>=FINISH:
        reason = 'ENTRY_AT_OR_AFTER_CUTOFF'
    elif not (0<path['target']<fill<path['stop']):
        reason = 'INVALID_FILL_STOP_TARGET_GEOMETRY'
    else:
        reason = None
    return fill,reason

def realized(path,cost):
    fill,rejection = price_entry(path,cost)
    if rejection or path['exit'] is None:
        return None
    if path['reason']=='STOP':
        return -1.0
    return (fill-path['exit_price'])/(path['stop']-fill)

def execute_p0(rule,indices,paths,model,cost):
    accepted,rejected,occupancy = [],[],[]
    active = None
    for signal_index in indices:
        if active is not None and (active['exit_index'] is None or signal_index<active['exit_index']):
            occupancy.append(dict(signal_index=signal_index,blocking_signal_index=active['signal_index'],
                                  blocking_exit_index=active['exit_index'],reason='P0_OCCUPIED_BEFORE_GEOMETRY'))
            continue
        path = paths[signal_index]
        fill,problem = price_entry(path,cost)
        if problem:
            rejected.append(dict(signal_index=signal_index,reason=problem))
            continue
        accepted.append(dict(config_id=rule['config_id'],execution_model=model,cost_ticks=cost,
            accepted_sequence=len(accepted)+1,signal_index=signal_index,exit_index=path['exit_index'],
            signal=path['signal'],entry=path['entry'],exit=path['exit'],reference_entry=path['reference_entry'],
            historical_fill=fill,stop=path['stop'],target=path['target'],risk_price=path['stop']-fill,
            exit_price=path['exit_price'],reason=path['reason'],r=realized(path,cost)))
        active = path
    return accepted,rejected,occupancy

class GateFailure(ValueError):
    pass

def risk_rate(sid):
    return 0.0075 if sid=='EUR_JPY_M15_SHORT' else 0.01

def simulate_book(book,scenario):
    """Exact archived event ordering and realized-balance risk accounting."""
    schedule=[]
    for i,r in enumerate(book):
        entry=date(r['entry']); exit=date(r['exit']) if r['exit'] else None
        if not BEGIN<=entry<PORTFOLIO_CUTOFF:
            raise GateFailure('Book entry outside common admission window')
        schedule.append((entry,1,r['sid'],i,r))
        if exit is not None and exit<=PORTFOLIO_CUTOFF:
            if exit<=entry or r['r'] is None:
                raise GateFailure('Invalid realized exit geometry')
            schedule.append((exit,0,r['sid'],i,r))
    schedule.sort(key=lambda event:event[:4])
    balance=peak=100.0; openrisk=0.0; active={}; events=[]; closed=0; maxpos=0; maxrisk=0.0; dd=floor_dd=0.0
    peak_time=BEGIN; dd_peak=dd_trough=BEGIN
    floor_peak=floor_trough=BEGIN
    equity_exits=[]
    for sequence,(time,kind,sid,i,r) in enumerate(schedule,1):
        before=balance; pnl=0.0
        if kind==0:
            cash,_=active.pop(i)
            openrisk-=cash
            pnl=cash*float(r['r'])
            balance+=pnl; closed+=1
            equity_exits.append((time,balance))
        else:
            cash=balance*risk_rate(sid)
            active[i]=(cash,r); openrisk+=cash
        if balance<=0 or not all(math.isfinite(x) for x in (balance,openrisk,peak)):
            raise GateFailure('Non-positive/non-finite equity cannot be interpreted')
        if balance>peak:
            peak=balance; peak_time=time
        closeddd=100*(balance/peak-1)
        floorequity=balance-openrisk
        floordd=100*(floorequity/peak-1)
        if closeddd<dd:
            dd=closeddd; dd_peak=peak_time; dd_trough=time
        if floordd<floor_dd:
            floor_dd=floordd; floor_peak=peak_time; floor_trough=time
        maxpos=max(maxpos,len(active)); maxrisk=max(maxrisk,100*openrisk/balance)
        currencies=defaultdict(float)
        for cash_active,trade in active.values():
            for currency in trade['pair'].split('_'):
                currencies[currency]+=cash_active
        events.append(dict(scenario=scenario,event_sequence=sequence,time=stamp(time),event='EXIT' if kind==0 else 'ENTRY',
                           sid=sid,pair=r['pair'],side=r['side'],source='CANDIDATE' if r['pair']=='EUR_CHF' else 'INCUMBENT',
                           source_record_index=i,signal=r['signal'],entry=r['entry'],exit=r['exit'],r=r['r'] if kind==0 else None,
                           risk_fraction=risk_rate(sid),risk_cash=cash,balance_before=before,pnl_cash=pnl,balance_after=balance,
                           active_positions=len(active),open_risk_cash=openrisk,open_risk_pct=100*openrisk/balance,
                           closed_peak=peak,closed_dd_pct=closeddd,open_risk_floor_equity=floorequity,open_risk_floor_dd_pct=floordd,
                           **{f'gross_{cur}_risk_pct':100*currencies[cur]/balance for cur in ('EUR','USD','GBP','JPY','AUD','CAD','CHF','NZD')}))
    first=min(date(r['entry']) for r in book)
    last=max((date(r['exit']) for r in book if r['exit'] and date(r['exit'])<=PORTFOLIO_CUTOFF),default=first)
    historic_years=(last-first).total_seconds()/(365.2425*86400)
    common_years=(PORTFOLIO_CUTOFF-BEGIN).total_seconds()/(365.2425*86400)
    summary=dict(scenario=scenario,strategies=len({r['sid'] for r in book}),trades=closed,open_at_cutoff=len(active),
                 balance_from_100=balance,historical_cagr_pct=100*((balance/100)**(1/historic_years)-1) if historic_years>0 else None,
                 common_window_cagr_pct=100*((balance/100)**(1/common_years)-1),max_closed_dd_pct=dd,max_open_risk_floor_dd_pct=floor_dd,
                 max_positions=maxpos,max_open_risk_pct=maxrisk,max_gross_EUR_risk_pct=max((e['gross_EUR_risk_pct'] for e in events),default=0),
                 max_gross_CHF_risk_pct=max((e['gross_CHF_risk_pct'] for e in events),default=0),
                 dd_peak=stamp(dd_peak),dd_trough=stamp(dd_trough),floor_peak=stamp(floor_peak),floor_trough=stamp(floor_trough),
                 first_entry=stamp(first),last_closed_exit=stamp(last),common_start=stamp(BEGIN),cutoff=stamp(PORTFOLIO_CUTOFF),
                 preserved_incumbent_records=sum(r['pair']!='EUR_CHF' for r in book),
                 candidate_closed_trades=sum(r['pair']=='EUR_CHF' and r['exit'] is not None and date(r['exit'])<=PORTFOLIO_CUTOFF for r in book),
                 candidate_open_at_cutoff=sum(r['pair']=='EUR_CHF' for _,r in active.values()),
                 candidate_closed_r=sum(r['r'] for r in book if r['pair']=='EUR_CHF' and r['exit'] and date(r['exit'])<=PORTFOLIO_CUTOFF))
    entry_sorted=sorted(book,key=lambda r:date(r['entry']))
    closed_sorted=sorted((r for r in book if r['exit'] and date(r['exit'])<=PORTFOLIO_CUTOFF),key=lambda r:date(r['exit']))
    return dict(summary=summary,events=events,exits=equity_exits,exit_times=[x[0] for x in equity_exits],book=book,
                entry_sorted=entry_sorted,entry_times=[date(r['entry']) for r in entry_sorted],
                closed_sorted=closed_sorted,closed_times=[date(r['exit']) for r in closed_sorted],event_times=[date(e['time']) for e in events],
                open_positions=[dict(source_record_index=i,risk_cash=cash,**r) for i,(cash,r) in active.items()])

def balance_at(sim,t):
    n=bisect.bisect_right(sim['exit_times'],t)-1
    return sim['exits'][n][1] if n>=0 else 100.0

def interval_report(sim,a,b):
    initial=balance_at(sim,a); ending=balance_at(sim,b)
    entries=sim['entry_sorted'][bisect.bisect_left(sim['entry_times'],a):bisect.bisect_left(sim['entry_times'],b)]
    exits=sim['closed_sorted'][bisect.bisect_right(sim['closed_times'],a):bisect.bisect_right(sim['closed_times'],b)]
    es=sim['events'][bisect.bisect_right(sim['event_times'],a):bisect.bisect_right(sim['event_times'],b)]
    peak=initial; dd=0.0
    for e in es:
        peak=max(peak,e['balance_after']); dd=min(dd,100*(e['balance_after']/peak-1))
    return dict(start=stamp(a),end=stamp(b),start_balance=initial,end_balance=ending,return_pct=100*(ending/initial-1),
                entry_count=len(entries),exit_count=len(exits),candidate_entries=sum(r['pair']=='EUR_CHF' for r in entries),
                candidate_exits=sum(r['pair']=='EUR_CHF' for r in exits),zero_entry_window=int(not entries),zero_exit_window=int(not exits),
                zero_candidate_entry_window=int(not any(r['pair']=='EUR_CHF' for r in entries)),closed_window_dd_pct=dd,
                candidate_pnl_cash=sum(e['pnl_cash'] for e in es if e['source']=='CANDIDATE'),
                incumbent_pnl_cash=sum(e['pnl_cash'] for e in es if e['source']=='INCUMBENT'))

def portfolio_months():
    bounds=[]; y,m=2005,1
    while datetime(y,m,1,tzinfo=UTC)<=PORTFOLIO_CUTOFF:
        bounds.append(datetime(y,m,1,tzinfo=UTC)); y,m=(y+1,1) if m==12 else (y,m+1)
    return bounds

def portfolio_periods():
    p=[(f'YEAR_{y}','calendar',datetime(y,1,1,tzinfo=UTC),min(datetime(y+1,1,1,tzinfo=UTC),PORTFOLIO_CUTOFF)) for y in range(2005,2027)]
    p += [(f'ERA_{a}_{b-1}','era',datetime(a,1,1,tzinfo=UTC),min(datetime(b,1,1,tzinfo=UTC),PORTFOLIO_CUTOFF)) for a,b in ((2005,2010),(2010,2016),(2016,2022),(2022,2027))]
    p += [(f'LATEST_{n}Y','recent',PORTFOLIO_CUTOFF.replace(year=PORTFOLIO_CUTOFF.year-n),PORTFOLIO_CUTOFF) for n in (1,2,3,5,10)]
    p += [('CHF_PRE_FLOOR','policy_diagnostic',BEGIN,date('2011-09-06T00:00:00Z')),
          ('CHF_FLOOR_PERIOD','policy_diagnostic',date('2011-09-06T00:00:00Z'),date('2015-01-15T00:00:00Z')),
          ('CHF_2015_01_15','policy_diagnostic',date('2015-01-15T00:00:00Z'),date('2015-01-16T00:00:00Z')),
          ('CHF_AFTER_2015_01_15','policy_diagnostic',date('2015-01-16T00:00:00Z'),PORTFOLIO_CUTOFF)]
    return p

def portfolio_reports(sim,tag):
    bounds=portfolio_months(); monthly=[]; period=[]; rolling=[]; rollsummary=[]
    for i,a in enumerate(bounds):
        b=bounds[i+1] if i+1<len(bounds) else PORTFOLIO_CUTOFF
        monthly.append(dict(tag,month=a.strftime('%Y-%m'),partial_month=int(b==PORTFOLIO_CUTOFF and b.day!=1),**interval_report(sim,a,b)))
    for label,kind,a,b in portfolio_periods():
        period.append(dict(tag,period=label,period_type=kind,partial_calendar_year=int(kind=='calendar' and b==PORTFOLIO_CUTOFF),**interval_report(sim,a,b)))
    for width in (12,24,36):
        windows=[dict(tag,months=width,**interval_report(sim,bounds[n-width],bounds[n])) for n in range(width,len(bounds))]
        rolling += windows
        worst=min(windows,key=lambda r:r['return_pct']); values=[r['return_pct'] for r in windows]
        rollsummary.append(dict(tag,months=width,completed_windows=len(windows),worst_return_pct=worst['return_pct'],worst_start=worst['start'],worst_end=worst['end'],
                                median_return_pct=percentile(values,.5),best_return_pct=max(values),positive_windows=sum(v>0 for v in values),
                                zero_entry_windows=sum(r['zero_entry_window'] for r in windows),zero_candidate_entry_windows=sum(r['zero_candidate_entry_window'] for r in windows)))
    return monthly,period,rolling,rollsummary

def entry_overlaps(candidate,incumbents,tag):
    rows=[]
    for r in candidate:
        now=date(r['entry'])
        live=[t for t in incumbents if date(t['entry'])<=now<date(t['exit'])]
        eur=[t for t in live if 'EUR' in t['pair'].split('_')]
        rows.append(dict(tag,candidate_sid=r['sid'],entry=r['entry'],exit=r['exit'],
                         incumbent_positions_at_entry=len(live),EUR_involved_positions_at_entry=len(eur),
                         incumbent_sids=';'.join(sorted(t['sid'] for t in live)),
                         EUR_involved_sids=';'.join(sorted(t['sid'] for t in eur)),
                         interpretation='Frozen incumbents at same timestamp after exits; gross currency involvement'))
    return rows

def equal_price(a,b):
    return math.isclose(a,b,rel_tol=1e-12,abs_tol=1e-10)

def percentile(values, p):
    if not values:
        return None
    ordered = sorted(values)
    x = (len(ordered)-1)*p
    left, right = math.floor(x), math.ceil(x)
    return ordered[left]+(ordered[right]-ordered[left])*(x-left)

def event_ties(sim,tag):
    bytime=defaultdict(list)
    for e in sim['events']:bytime[e['time']].append(e)
    return [dict(tag,time=time,events_at_timestamp=len(records),tie_rank=rank,
                 event=e['event'],sid=e['sid'],source_record_index=e['source_record_index'],
                 event_sequence=e['event_sequence'],balance_before=e['balance_before'],risk_cash=e['risk_cash'])
            for time,records in bytime.items() if len(records)>1 for rank,e in enumerate(records,1)]

def read_rows(raw):
    return list(csv.DictReader(io.StringIO(raw.decode())))


def typed_parity(checks,label,actual,reference):
    gate(checks,label+' row count',len(reference),len(actual))
    expected=[]
    for row,ref in zip(actual,reference):
        if set(row)!=set(ref):raise ValueError('Parity schema mismatch '+label)
        converted={}
        for key,value in row.items():
            text=ref[key]
            if value is None:target=None if text=='' else text
            elif isinstance(value,bool):target=text=='True'
            elif isinstance(value,int):target=int(text)
            elif isinstance(value,float):target=float(text)
            else:target=text
            converted[key]=target
        expected.append(converted)
    canonical=lambda r:json.dumps(r,sort_keys=True,separators=(',',':'),allow_nan=False).encode()
    gate(checks,label+' complete ordered typed fields SHA',fingerprint(canonical(expected)),fingerprint(canonical(actual)))


def load_portfolio_reference(checks):
    data=unpack(PORTFOLIO_REFERENCE_B85,PORTFOLIO_REFERENCE_SHA)
    with zipfile.ZipFile(io.BytesIO(data)) as z:
        gate(checks,'Portfolio reference CRC',None,z.testzip())
        gate(checks,'Reference unique filenames',len(z.namelist()),len(set(z.namelist())))
        blobs={n:z.read(n) for n in z.namelist()}
    manifest=json.loads(blobs['file_manifest.json'])
    gate(checks,'Exact reference file set',sorted(manifest),sorted(n for n in blobs if n!='file_manifest.json'))
    for n,r in manifest.items():
        gate(checks,'Reference size '+n,r['size_bytes'],len(blobs[n]))
        gate(checks,'Reference SHA '+n,r['sha256'],fingerprint(blobs[n]))
    gate(checks,'Predeclared baseline JSON pin',BASELINE_INPUTS_SHA,fingerprint(json_bytes(BASELINE_INPUTS)))
    gate(checks,'Predeclared implementation specification pin',ADMISSION_SPEC_SHA,fingerprint(json_bytes(ADMISSION_SPEC)))
    gate(checks,'Frozen primary SHORT definition',ADMISSION_SPEC['primary_short'],SHORT_RULE)
    gate(checks,'Frozen LONG research identity',ADMISSION_SPEC['candidate_research_id'],LONG_SID)
    gate(checks,'Frozen matched costs',ADMISSION_SPEC['cost_ticks'],list(COSTS))
    gate(checks,'Frozen exit models',ADMISSION_SPEC['models'],list(MODELS))
    gate(checks,'Frozen portfolio clock cutoff',ADMISSION_SPEC['portfolio_cutoff'],stamp(PORTFOLIO_CUTOFF))
    gate(checks,'Predeclared six complete P32 summaries',BASELINE_INPUTS['expected_p32_baselines'],read_rows(blobs['baseline_portfolio_summary.csv']))
    gate(checks,'Frozen P31 ledger bytes',BASELINE_INPUTS['archived31']['ledger_sha256'],fingerprint(blobs['incumbent_frozen_book.json']))
    provenance=json.loads(blobs['provenance.json'])
    gate(checks,'Pass13 archive provenance',BASELINE_INPUTS['reference_provenance']['validated_pass13_archive_sha256'],provenance['pass13_archive_sha256'])
    gate(checks,'Confirmed LONG archive provenance',BASELINE_INPUTS['candidate_confirmed_archive_sha256'],provenance['long_archive_sha256'])
    book=json.loads(blobs['incumbent_frozen_book.json'])
    gate(checks,'P31 count',3332,len(book));gate(checks,'P31 strategies',31,len({r['sid'] for r in book}))
    gate(checks,'No old EURCHF entries',True,all(r['pair']!='EUR_CHF' for r in book))
    gate(checks,'P31 closed causal book',True,all(BEGIN<=date(r['entry'])<date(r['exit'])<=PORTFOLIO_CUTOFF and math.isfinite(r['r']) for r in book))
    gate(checks,'P31 unique identities',len(book),len({(r['sid'],r['signal']) for r in book}))
    registry=[dict(sid=sid,risk_fraction=risk_rate(sid),trades=sum(r['sid']==sid for r in book)) for sid in sorted({r['sid'] for r in book})]
    typed_parity(checks,'P31 pinned registry',registry,BASELINE_INPUTS['archived31_registry'])
    aliases=ADMISSION_SPEC['archive_to_live_aliases'];live=ADMISSION_SPEC['supplied_live_registry']
    gate(checks,'Exactly32 supplied live registry',32,len(live))
    gate(checks,'Alias map covers all31 incumbents',sorted({r['sid'] for r in book}),sorted(aliases))
    gate(checks,'Alias maps bijectively to old31',31,len(set(aliases.values())))
    gate(checks,'Complete current registry mapping',sorted(live),sorted(list(aliases.values())+[SHORT_SID]))
    for r in book:
        target=live[aliases[r['sid']]]
        if any(r[a]!=target[b] for a,b in [('pair','pair'),('side','side'),('tf','timeframe')]) or r['rr'] not in target['rr']:
            raise ValueError('Archived trade disagrees with supplied live registry '+r['sid'])
        if risk_rate(r['sid'])!=target['risk_percent']/100:raise ValueError('Registry risk differs '+r['sid'])
    own={};active=[]
    for r in sorted(book,key=lambda r:(date(r['entry']),r['sid'])):
        if r['sid'] in own and date(r['entry'])<own[r['sid']]:raise ValueError('P31 own-ID overlap')
        own[r['sid']]=date(r['exit'])
        if r['pair']=='AUD_JPY':
            active=[x for x in active if date(x['exit'])>date(r['entry'])]
            if any(x['side']!=r['side'] for x in active):raise ValueError('P31 AUDJPY opposite overlap')
            active.append(r)
    return blobs,book,registry


def path_record(side,path,model,cost,sequence):
    fill,problem=price_entry(path,cost) if side=='SELL' else entry_problem(path,cost)
    if date(path['entry'])>=PORTFOLIO_CUTOFF:problem='ENTRY_AT_OR_AFTER_PORTFOLIO_CUTOFF'
    if problem:return None,problem
    risk=path['stop']-fill if side=='SELL' else fill-path['stop']
    value=None if path['exit_price'] is None else ((fill-path['exit_price'])/risk if side=='SELL' else (path['exit_price']-fill)/risk)
    out={k:path[k] for k in ('signal_index','exit_index','signal','entry','exit','reference_entry','stop','target','exit_price','reason')}
    out.update(config_id=SHORT_RULE['config_id'] if side=='SELL' else CANDIDATE,
        execution_model=model,cost_ticks=cost,accepted_sequence=sequence,historical_fill=fill,risk_price=risk,r=value)
    return out,None


def joint_replay(short_ids,long_ids,short_paths,long_paths,model,cost,include_long):
    raw=[(date(short_paths[i]['entry']),SHORT_SID,i,'SELL') for i in short_ids]
    if include_long:raw += [(date(long_paths[model,i]['entry']),LONG_SID,i,'BUY') for i in long_ids]
    raw.sort(key=lambda r:r[:3])
    ledgers={'SELL':[],'BUY':[]};last={};audit=[]
    for clock,sid,i,side in raw:
        path=short_paths[i] if side=='SELL' else long_paths[model,i]
        tag=dict(execution_model=model,cost_ticks=cost,strategy_id=sid,side=side,signal_index=i,
                 signal=path['signal'],entry=path['entry'],blocker_strategy_id=None,blocker_signal_index=None,
                 blocker_exit_index=None,blocker_exit=None,own_source_index_guard=True,
                 opposite_clock_guard=True,attempt_tie_order='LEXICAL_STRATEGY_ID_THEN_SIGNAL_INDEX')
        previous=last.get(side)
        if previous is not None and (previous['exit_index'] is None or i<previous['exit_index']):
            audit.append(dict(tag,status='BLOCKED_P0',blocker_strategy_id=sid,
                blocker_signal_index=previous['signal_index'],blocker_exit_index=previous['exit_index'],blocker_exit=previous['exit']))
            continue
        record,problem=path_record(side,path,model,cost,len(ledgers[side])+1)
        if problem:
            audit.append(dict(tag,status=problem));continue
        other=last.get('BUY' if side=='SELL' else 'SELL')
        if other is not None and (other['exit'] is None or date(other['exit'])>clock):
            if include_long:
                other_sid=LONG_SID if side=='SELL' else SHORT_SID
                audit.append(dict(tag,status='BLOCKED_OPPOSITE',blocker_strategy_id=other_sid,
                    blocker_signal_index=other['signal_index'],blocker_exit_index=other['exit_index'],blocker_exit=other['exit']))
                continue
            raise ValueError('Unexpected opposite position in short-only baseline')
        if record['exit'] is not None and date(record['exit'])<=clock:raise ValueError('Exit cannot precede its entry')
        ledgers[side].append(record);last[side]=record
        audit.append(dict(tag,status='ACCEPTED_OPEN' if record['exit'] is None else 'ACCEPTED_CLOSED'))
    return ledgers,audit


def to_book(records,side):
    return [dict(sid=SHORT_SID if side=='SELL' else LONG_SID,pair='EUR_CHF',side=side,tf='H1',rr=3.5 if side=='SELL' else 3.,
        signal=r['signal'],entry=r['entry'],exit=r['exit'],r=r['r']) for r in records]


def censored_full(records):
    output=[]
    for r in records:
        if date(r['entry'])>=PORTFOLIO_CUTOFF:continue
        row={k:r[k] for k in LEDGER_FIELDS}
        if row['exit'] is None or date(row['exit'])>PORTFOLIO_CUTOFF:
            row.update(exit_index=None,exit=None,exit_price=None,reason='OPEN_AT_DATA_END',r=None)
        output.append(row)
    return output


def enrich_intervals(records,sim):
    es=sim['events'];bycomponent={component:[e for e in es if e['event']=='EXIT' and portfolio_component(e['sid'])==component] for component in ('LONG','SHORT','OTHER31')}
    index={k:([date(e['time']) for e in events],events) for k,events in bycomponent.items()}
    for row in records:
        a,b=date(row['start']),date(row['end'])
        entries=sim['entry_sorted'][bisect.bisect_left(sim['entry_times'],a):bisect.bisect_left(sim['entry_times'],b)]
        exits=sim['closed_sorted'][bisect.bisect_right(sim['closed_times'],a):bisect.bisect_right(sim['closed_times'],b)]
        for component in ('LONG','SHORT','OTHER31'):
            ts,events=index[component];lo=bisect.bisect_right(ts,a);hi=bisect.bisect_right(ts,b)
            row[component.lower()+'_entries']=sum(portfolio_component(r['sid'])==component for r in entries)
            row[component.lower()+'_exits']=sum(portfolio_component(r['sid'])==component for r in exits)
            row[component.lower()+'_pnl_cash']=sum(e['pnl_cash'] for e in events[lo:hi])
        row['zero_long_entry_window']=int(row['long_entries']==0)
        if not equal_price(sum(row[k+'_pnl_cash'] for k in ('long','short','other31')),row['candidate_pnl_cash']+row['incumbent_pnl_cash']):
            raise ValueError('Interval component cash reconciliation')
    return records


def portfolio_component(sid):
    return 'LONG' if sid==LONG_SID else 'SHORT' if sid==SHORT_SID else 'OTHER31'


def cash_identity_close(actual,expected,scale):
    # Float summation/subtraction of very large inherited model balances can
    # leave small residuals when the true incremental cash is near zero.
    # Bound tolerance by the balances reconciled, not that tiny difference.
    return math.isclose(actual,expected,rel_tol=1e-12,abs_tol=1e-12*max(1.,scale))


def marginal_trades(current,baseline,scenario,reference,side,audit):
    now={r['signal_index']:r for r in current};old={r['signal_index']:r for r in baseline}
    attempts={r['signal_index']:r for r in audit if r['side']==side};changes=[]
    for i in sorted(set(now)|set(old)):
        a,b=now.get(i),old.get(i);chosen=a or b;attempt=attempts.get(i,{})
        if a and b and any(not close_enough(a[k],b[k]) for k in LEDGER_FIELDS if k!='accepted_sequence'):
            raise ValueError('Retained signal outcome/geometry changed')
        changes.append(dict(scenario=scenario,reference=reference,side=side,strategy_id=SHORT_SID if side=='SELL' else LONG_SID,
            signal_index=i,signal=chosen['signal'],entry=chosen['entry'],change='RETAINED' if a and b else 'ADDED_OR_RECOVERED' if a else 'REMOVED',
            current_r=a['r'] if a else None,reference_r=b['r'] if b else None,current_open=int(a is not None and a['r'] is None),
            reference_open=int(b is not None and b['r'] is None),joint_disposition=attempt.get('status'),
            blocker_strategy_id=attempt.get('blocker_strategy_id'),blocker_signal_index=attempt.get('blocker_signal_index')))
    return changes


def paired_cash_rows(sim,base,tag,checks):
    def group(s):
        out={}
        for e in s['events']:
            key=(e['sid'],e['signal']);out.setdefault(key,{})[e['event']]=e
        return out
    now,old=group(sim),group(base);rows=[]
    for sid,signal in sorted(set(now)|set(old)):
        a,b=now.get((sid,signal),{}),old.get((sid,signal),{});ae,be=a.get('ENTRY'),b.get('ENTRY');ax,bx=a.get('EXIT'),b.get('EXIT')
        cp=ax['pnl_cash'] if ax else 0.;bp=bx['pnl_cash'] if bx else 0.
        component=portfolio_component(sid)
        change='RETAINED_RESIZED' if ae and be else 'ADDED' if ae else 'REMOVED'
        if component=='OTHER31' and change!='RETAINED_RESIZED':raise ValueError('Old31 acceptance changed')
        if ae and be and any(ae[k]!=be[k] for k in ('sid','pair','side','signal','entry','exit','risk_fraction')):raise ValueError('Retained book changed')
        rows.append(dict(tag,component=component,strategy_id=sid,signal=signal,entry=(ae or be)['entry'],change=change,
            current_exit=ax['time'] if ax else None,baseline_exit=bx['time'] if bx else None,
            current_risk_cash=ae['risk_cash'] if ae else 0.,baseline_risk_cash=be['risk_cash'] if be else 0.,
            current_r=ax['r'] if ax else None,baseline_r=bx['r'] if bx else None,current_pnl_cash=cp,baseline_pnl_cash=bp,delta_pnl_cash=cp-bp))
    total=sim['summary']['balance_from_100']-base['summary']['balance_from_100']
    gate(checks,tag['scenario']+' total cash identity',True,equal_price(total,sum(r['delta_pnl_cash'] for r in rows)))
    return rows


def pair_reports(current,baseline,tag,identifiers):
    cmap={tuple(r[k] for k in identifiers):r for r in current};bmap={tuple(r[k] for k in identifiers):r for r in baseline}
    if set(cmap)!=set(bmap):raise ValueError('Paired report interval universe differs')
    out=[]
    for key,c in cmap.items():
        b=bmap[key];row=dict(tag,**dict(zip(identifiers,key)))
        for field in ('return_pct','closed_window_dd_pct','entry_count','exit_count','long_entries','short_entries','other31_entries',
                      'long_pnl_cash','short_pnl_cash','other31_pnl_cash','zero_long_entry_window'):
            row.update({field+'_p32':b[field],field+'_p33':c[field],field+'_delta':c[field]-b[field]})
        cashdelta=sum(c[k+'_pnl_cash']-b[k+'_pnl_cash'] for k in ('long','short','other31'))
        scale=max(c['end_balance'],c['start_balance'],b['end_balance'],b['start_balance'])
        if not cash_identity_close(cashdelta,(c['end_balance']-c['start_balance'])-(b['end_balance']-b['start_balance']),scale):
            raise ValueError('Paired interval cash delta identity')
        row['net_cash_delta']=cashdelta;out.append(row)
    return out


def weak_attribution(sim,base,windows,tag):
    rows=[]
    for label,a,b in windows:
        for sid in sorted({r['sid'] for r in sim['book']}|{r['sid'] for r in base['book']}):
            new=[e for e in sim['events'] if e['sid']==sid and e['event']=='EXIT' and a<date(e['time'])<=b]
            old=[e for e in base['events'] if e['sid']==sid and e['event']=='EXIT' and a<date(e['time'])<=b]
            nc=sum(e['pnl_cash'] for e in new);oc=sum(e['pnl_cash'] for e in old)
            rows.append(dict(tag,window=label,start=stamp(a),end=stamp(b),strategy_id=sid,component=portfolio_component(sid),
                current_exits=len(new),baseline_exits=len(old),current_pnl_cash=nc,baseline_pnl_cash=oc,delta_pnl_cash=nc-oc,
                current_return_contribution_pct=100*nc/balance_at(sim,a),baseline_return_contribution_pct=100*oc/balance_at(base,a)))
    return rows


def legacy_baseline_summary(sim,anchor,tag,rollsum,records,audit,prefix_count):
    summary=dict(tag,**{k:v for k,v in sim['summary'].items() if k!='scenario'})
    for span in (12,24,36):summary[f'worst_{span}m_return_pct']=next(r['worst_return_pct'] for r in rollsum if r['months']==span)
    currentcash=sum(e['pnl_cash'] for e in sim['events'] if e['source']=='CANDIDATE')
    oldcash=sum(e['pnl_cash'] for e in sim['events'] if e['source']=='INCUMBENT');basecash=sum(e['pnl_cash'] for e in anchor['events'])
    summary.update(delta_common_cagr_pp=summary['common_window_cagr_pct']-anchor['summary']['common_window_cagr_pct'],
        delta_closed_dd_pp=summary['max_closed_dd_pct']-anchor['summary']['max_closed_dd_pct'],
        delta_floor_dd_pp=summary['max_open_risk_floor_dd_pct']-anchor['summary']['max_open_risk_floor_dd_pct'],
        delta_max_positions=summary['max_positions']-anchor['summary']['max_positions'],
        delta_max_open_risk_pp=summary['max_open_risk_pct']-anchor['summary']['max_open_risk_pct'],
        direct_candidate_pnl_cash=currentcash,incumbent_resizing_delta_cash=oldcash-basecash,
        delta_ending_equity=summary['balance_from_100']-anchor['summary']['balance_from_100'],
        candidate_qualified_at_cutoff=len(audit),candidate_accepted_entries=len(records),
        candidate_p0_blocked=sum(r['status']=='BLOCKED_P0' for r in audit),
        candidate_invalid_unblocked=sum(r['status'] not in ('ACCEPTED_OPEN','ACCEPTED_CLOSED','BLOCKED_P0') for r in audit),
        candidate_cutoff_ledger_sha256=ledger_digest(records),cutoff_completed_candles=prefix_count)
    return summary


def admission_software_checks():
    output=[]
    def check(label,value):
        if not value:raise ValueError('Admission synthetic failure '+label)
        output.append(dict(check=label,status='PASS',evidence='SYNTHETIC_SOFTWARE_ONLY'))
    t=date('2020-01-01T00:00:00Z');model=MODELS[1]
    def path(i,exit_index,exit_clock=None,side='SELL',target=None):
        return dict(signal_index=i,signal=stamp(t+i*HOUR),entry=stamp(t+(i+1)*HOUR),exit_index=exit_index,
            exit=stamp(exit_clock or t+(exit_index+1)*HOUR) if exit_index is not None else None,
            reference_entry=1.1,stop=1.2 if side=='SELL' else 1.,target=target or (.75 if side=='SELL' else 1.4),
            exit_price=(1.2 if side=='SELL' else 1.) if exit_index is not None else None,
            reason='STOP' if exit_index is not None else 'OPEN_AT_DATA_END')
    sp={0:path(0,4),4:path(4,6)};lp={(model,1):path(1,3,side='BUY')}
    led,a=joint_replay([0,4],[1],sp,lp,model,10,True)
    check('Short blocks opposite long; exit-index own reentry',[r['signal_index'] for r in led['SELL']]==[0,4] and a[1]['status']=='BLOCKED_OPPOSITE')
    lp={(model,0):path(0,4,side='BUY')};sp={1:path(1,3),4:path(4,6)}
    led,a=joint_replay([1,4],[0],sp,lp,model,10,True)
    check('Long can block short then release on actual close',[r['signal_index'] for r in led['SELL']]==[4] and a[1]['status']=='BLOCKED_OPPOSITE')
    sp={0:path(0,4),3:path(3,5),4:path(4,6)};lp={(model,3):path(3,5,side='BUY')}
    sp[0]=path(0,4,t+4*HOUR)
    led,a=joint_replay([0,3,4],[3],sp,lp,model,10,True)
    check('Opening exit releases opposite at exact entry clock',led['BUY'][0]['signal_index']==3)
    check('Own source-index rule remains stricter at opening gap',next(r for r in a if r['side']=='SELL' and r['signal_index']==3)['status']=='BLOCKED_P0')
    check('Blocked attempts do not claim occupancy',next(r for r in a if r['side']=='SELL' and r['signal_index']==4)['blocker_strategy_id']==LONG_SID)
    sp={0:path(0,None),1:path(1,3)};lp={(model,2):path(2,4,side='BUY')}
    led,a=joint_replay([0,1],[2],sp,lp,model,10,True)
    check('Open end position keeps own and pair occupied',led['SELL'][0]['r'] is None and [r['status'] for r in a]==['ACCEPTED_OPEN','BLOCKED_P0','BLOCKED_OPPOSITE'])
    sp={0:path(0,4,target=1.09995),2:path(2,4)};lp={(model,1):path(1,2,side='BUY')}
    led,a=joint_replay([0,2],[1],sp,lp,model,10,True)
    check('Invalid geometry never claims pair occupancy',a[0]['status']=='INVALID_FILL_STOP_TARGET_GEOMETRY' and len(led['BUY'])==1 and len(led['SELL'])==1)
    sp={0:path(0,2)};lp={(model,0):path(0,2,side='BUY')}
    led,a=joint_replay([0],[0],sp,lp,model,10,True)
    check('Simultaneous attempts use frozen lexical strategy order',a[0]['strategy_id']==min(SHORT_SID,LONG_SID) and a[1]['status']=='BLOCKED_OPPOSITE')
    sp={1:path(1,5),3:path(3,6)};lp={(model,0):path(0,2,side='BUY')}
    base,_=joint_replay([1,3],[],sp,lp,model,10,False)
    joined,a=joint_replay([1,3],[0],sp,lp,model,10,True)
    check('Replay recovers later raw short blocked in standalone',base['SELL'][0]['signal_index']==1 and joined['SELL'][0]['signal_index']==3 and a[1]['status']=='BLOCKED_OPPOSITE')
    def trade(sid,en,ex,value,pair='EUR_USD'):
        return dict(sid=sid,entry=stamp(en),exit=stamp(ex) if ex else None,r=value,pair=pair,side='BUY',tf='H1',rr=3.,signal=stamp(en-HOUR))
    sim=simulate_book([trade('B',t,t+HOUR,2),trade('A',t+HOUR,t+2*HOUR,-1)],'TEST')
    check('Exits before entries at exact same timestamp',[e['event'] for e in sim['events'][1:3]]==['EXIT','ENTRY'])
    check('Realized equity entry sizing',equal_price(sim['events'][2]['risk_cash'],1.02) and equal_price(sim['summary']['balance_from_100'],100.98))
    check('Existing EURJPY M15 short risk preserved',equal_price(simulate_book([trade('EUR_JPY_M15_SHORT',t,t+HOUR,-1,'EUR_JPY')],'T')['summary']['balance_from_100'],99.25))
    op=simulate_book([trade(LONG_SID,t,None,None,'EUR_CHF')],'T')
    check('Open outcome has no realized cash',op['summary']['balance_from_100']==100. and op['summary']['open_at_cutoff']==1)
    check('Open risk floor allocated and EUR/CHF involvement',equal_price(op['summary']['max_open_risk_floor_dd_pct'],-1.) and op['summary']['max_gross_CHF_risk_pct']==1.)
    check('Gap loss may exceed nominal floor',simulate_book([trade('GAP',t,t+HOUR,-2)],'T')['summary']['max_closed_dd_pct']<-1.99)
    check('No invented global position cap',simulate_book([trade(str(i),t,t+HOUR,-1) for i in range(7)],'T')['summary']['max_positions']==7)
    tie=simulate_book([trade('B',t,t+HOUR,-1),trade('A',t,t+HOUR,2)],'T')
    check('Lexical portfolio event order',[e['sid'] for e in tie['events'][:2]]==['A','B'])
    check('Entry interval left closed, exit interval right closed',interval_report(sim,t,t+HOUR)['entry_count']==1 and interval_report(sim,t,t+HOUR)['exit_count']==1)
    bars=[(PORTFOLIO_CUTOFF.replace(hour=16,minute=0),1.,1.1,.99,1.),(PORTFOLIO_CUTOFF.replace(hour=17,minute=0),1.,1.1,.99,1.),(PORTFOLIO_CUTOFF.replace(hour=18,minute=0),1.,1.1,.5,1.)]
    check('Forming hour excluded from causal prefix',len([r for r in bars if r[0]+HOUR<=PORTFOLIO_CUTOFF])==2)
    check('Partial September excluded from complete month rolling',portfolio_months()[-1]==date('2026-09-01T00:00:00Z') and sum(len(range(w,len(portfolio_months()))) for w in (12,24,36))==711)
    check('Cash tolerance accepts rounding only at large balance scale',cash_identity_close(.000001,0.,1e10) and not cash_identity_close(1.,0.,1e10))
    return output


def build_reports(checks,fields):
    reference,oldbook,registry=load_portfolio_reference(checks)
    control,counts=build_long_control_reports(checks,fields)
    source=unpack(SOURCE_B85,SOURCE_BYTE_SHA);candles=load_candles(source)
    full_short,short_features,_,_=identify_original(candles)
    typed_parity(checks,'Full primary SHORT raw features',short_features,read_rows(reference['short_raw_signal_features.csv']))
    expected_short=[int(r['signal_index']) for r in read_rows(reference['short_raw_signal_membership.csv'])]
    gate(checks,'Full SHORT raw memberships',expected_short,full_short)
    prefix=[r for r in candles if r[0]+HOUR<=PORTFOLIO_CUTOFF]
    gate(checks,'Completed common-cutoff candle count',137624,len(prefix))
    gate(checks,'Last completed H1 source start','2026-09-18T20:00:00Z',stamp(prefix[-1][0]))
    short_ids,cutoff_short_features,_,_=identify_original(prefix)
    long_features=extract_features(prefix)
    long_ids=[r['signal_index'] for r in long_features if entry_qualifies(r,1.375) and date(r['entry'])<PORTFOLIO_CUTOFF]
    full_long_features=extract_features(candles)
    gate(checks,'Full/prefix SHORT membership causality',[i for i in full_short if candles[i][0]+HOUR<PORTFOLIO_CUTOFF],short_ids)
    gate(checks,'Full/prefix LONG feature causality',fingerprint(json_bytes([r for r in full_long_features if r['signal_index']<len(prefix)])),fingerprint(json_bytes(long_features)))
    gate(checks,'Full/prefix SHORT feature causality',fingerprint(json_bytes([r for r in short_features if r['signal_index']<len(prefix)])),fingerprint(json_bytes(cutoff_short_features)))
    longfull=[parse_reference_record(r) for r in read_rows(control['accepted_ledgers.csv']) if r['config_id']==CANDIDATE]
    shortfull_expected=[parse_reference_record(r) for r in read_rows(reference['short_full_accepted_ledgers.csv'])]
    shortfull=[];standalone_long={};standalone_short={};paths={};pathrows=[]
    for model in MODELS:
        fullpaths={i:isolated_path(candles,i,model) for i in full_short}
        sp={i:isolated_path(prefix,i,model) for i in short_ids};lp=construct_paths(prefix,long_ids)
        paths[model]=(sp,lp)
        pathrows.extend(dict(strategy_id=SHORT_SID,side='SELL',execution_model=model,**r) for r in sp.values())
        pathrows.extend(dict(strategy_id=LONG_SID,side='BUY',**r) for (m,i),r in lp.items() if m==model)
        for cost in COSTS:
            records,_,_=execute_p0(SHORT_RULE,full_short,fullpaths,model,cost)
            gate(checks,'Full primary SHORT complete ledger '+model+str(cost),ledger_digest([r for r in shortfull_expected if r['execution_model']==model and r['cost_ticks']==cost]),ledger_digest(records))
            shortfull.extend(records)
            led,audit=joint_replay(short_ids,[],sp,lp,model,cost,False)
            standalone_short[model,cost]=led['SELL']
            gate(checks,'Causal SHORT full-censored ledger '+model+str(cost),ledger_digest(censored_full(records)),ledger_digest(led['SELL']))
            own,bad,blocked=simulate(CANDIDATE,model,cost,long_ids,lp)
            if bad or blocked:raise ValueError('Frozen LONG changed invalid/p0 status at cutoff')
            standalone_long[model,cost]=own
            gate(checks,'Causal LONG full-censored ledger '+model+str(cost),ledger_digest(censored_full([r for r in longfull if r['execution_model']==model and r['cost_ticks']==cost])),ledger_digest(own))
    payload={('long_full_control_'+n if n not in ('source_candles.csv','data_gaps.csv') else n):b for n,b in control.items()}
    anchor=simulate_book(oldbook,'P31_BASELINE')
    for k,v in BASELINE_INPUTS['archived31']['expected_metrics'].items():gate(checks,'Exact P31 accounting '+k,v,anchor['summary'][k])
    outputs=defaultdict(list);sims={};case_reports={};baseline_tables=defaultdict(list);paired=[];allbooks=[]
    # Reproduce all six baseline outputs before any LONG addition is computed.
    for model in MODELS:
        for cost in COSTS:
            name=f'P32_PRIMARY_{model}_{cost}T';tag=dict(scenario=name,role='PRIMARY',strategy_id=SHORT_SID,rr=3.5,execution_model=model,cost_ticks=cost)
            records=standalone_short[model,cost];book=oldbook+to_book(records,'SELL');sim=simulate_book(book,name)
            sp,lp=paths[model];_,audit=joint_replay(short_ids,[],sp,lp,model,cost,False)
            report=portfolio_reports(sim,tag)
            summary=legacy_baseline_summary(sim,anchor,tag,report[3],records,audit,len(prefix))
            baseline_tables['portfolio_summary.csv'].append(summary)
            baseline_tables['candidate_cutoff_ledgers.csv'].extend(dict(tag,**{k:v for k,v in r.items() if k not in tag}) for r in records)
